<script setup>
import { onMounted, ref, watch } from "vue";
import UiIcon from "../../components/UiIcon.vue";
import { createAdminUser, getAdminUsers, updateAdminUser } from "../../services/adminRepository";
const items = ref([]); const total = ref(0); const page = ref(1); const loading = ref(true); const error = ref(""); const query = ref(""); const role = ref(""); const active = ref(""); const saving = ref(false); const show = ref(false); const toast = ref("");
const form = ref({ username:"", password:"", display_name:"", role:"student", student_number:"", teacher_number:"", college:"", major:"", grade:"" });
const roleLabel = { student:"学生", teacher:"教师", admin:"管理员" };
async function load(){ loading.value=true; error.value=""; try{ const r=await getAdminUsers({page:page.value,query:query.value||undefined,role:role.value||undefined,is_active:active.value===""?undefined:active.value==="true"}); items.value=r.items; total.value=r.total; }catch(e){error.value=e.response?.data?.message||e.message||"账号加载失败"}finally{loading.value=false} }
function reset(){form.value={username:"",password:"",display_name:"",role:"student",student_number:"",teacher_number:"",college:"",major:"",grade:""};show.value=true}
async function submit(){saving.value=true;try{await createAdminUser({...form.value,student_number:form.value.role==="student"?form.value.student_number||null:null,teacher_number:form.value.role==="teacher"?form.value.teacher_number||null:null});show.value=false;toast.value="账号已创建";await load()}catch(e){toast.value=e.response?.data?.message||"账号创建失败"}finally{saving.value=false}}
async function toggle(item){try{await updateAdminUser(item.id,{is_active:!item.is_active});toast.value=item.is_active?"账号已停用":"账号已恢复";await load()}catch(e){toast.value=e.response?.data?.message||"状态更新失败"}}
let timer; watch([query,role,active],()=>{page.value=1;clearTimeout(timer);timer=setTimeout(load,260)}); onMounted(load);
</script>
<template><main class="portal-page admin-portal page-enter"><div v-if="toast" class="portal-toast" role="status"><UiIcon name="PhCheckCircle" />{{ toast }}</div><div class="portal-heading"><div><span class="portal-kicker">账号与角色</span><h1>账号管理</h1><p>服务端分页、筛选和后端 RBAC 保护的账号列表。</p></div><button class="primary-button" @click="reset"><UiIcon name="PhUserPlus" />创建账号</button></div><section class="portal-toolbar"><div class="portal-search"><UiIcon name="PhMagnifyingGlass" /><input v-model="query" placeholder="搜索姓名、用户名、学号或工号" /></div><select v-model="role"><option value="">全部角色</option><option value="student">学生</option><option value="teacher">教师</option><option value="admin">管理员</option></select><select v-model="active"><option value="">全部状态</option><option value="true">正常</option><option value="false">已停用</option></select><span>{{ total }} 个账号</span></section><div v-if="loading" class="portal-loading"><i v-for="n in 4" :key="n"></i></div><div v-else-if="error" class="portal-error"><strong>{{ error }}</strong><button class="secondary-button" @click="load">重试</button></div><section v-else class="portal-panel account-table"><div class="account-head"><span>用户</span><span>学号 / 工号</span><span>院系</span><span>角色</span><span>状态</span><span>操作</span></div><article v-for="item in items" :key="item.id" class="account-row"><div><span class="user-initial">{{ (item.display_name||item.username).slice(0,1) }}</span><span><strong>{{ item.display_name||item.username }}</strong><small>@{{ item.username }}</small></span></div><span>{{ item.student_number||item.teacher_number||"-" }}</span><span>{{ item.college||"未填写" }}<small>{{ item.major||"" }}</small></span><em>{{ roleLabel[item.role] }}</em><b :class="{inactive:!item.is_active}">{{ item.is_active?"正常":"已停用" }}</b><button @click="toggle(item)">{{ item.is_active?"停用":"恢复" }}</button></article><div v-if="!items.length" class="portal-empty">暂无符合条件的账号</div></section><div class="tch-pagination"><button :disabled="page<=1" @click="page--;load()">上一页</button><span>{{ page }} / {{ Math.max(1,Math.ceil(total/20)) }}</span><button :disabled="page>=Math.ceil(total/20)" @click="page++;load()">下一页</button></div><div v-if="show" class="portal-overlay" @keydown.esc="show=false"><form class="portal-drawer" @submit.prevent="submit"><div class="drawer-head"><div><span>创建账号</span><h2>新增平台用户</h2></div><button type="button" class="icon-button" @click="show=false"><UiIcon name="PhX" /></button></div><label>用户名<input v-model="form.username" required minlength="3" /></label><label>初始密码<input v-model="form.password" required minlength="8" type="password" /></label><label>姓名<input v-model="form.display_name" required /></label><label>角色<select v-model="form.role"><option value="student">学生</option><option value="teacher">教师</option><option value="admin">管理员</option></select></label><label v-if="form.role==='student'">学号<input v-model="form.student_number" /></label><label v-if="form.role==='teacher'">工号<input v-model="form.teacher_number" /></label><div class="form-pair"><label>学院<input v-model="form.college" /></label><label>专业<input v-model="form.major" /></label></div><label v-if="form.role==='student'">年级<input v-model="form.grade" /></label><div class="drawer-actions"><button type="button" class="secondary-button" @click="show=false">取消</button><button class="primary-button" :disabled="saving">{{ saving?"保存中…":"创建账号" }}</button></div></form></div></main></template>
